  ADD COLUMN lock_id uuid,
  ADD COLUMN locked_at timestamptz;
```

## Handler

```ts
import { createHash, randomUUID } from "node:crypto";
import type { Request, Response, NextFunction } from "express";
import { Pool } from "pg";

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

const MAX_KEY_LENGTH = 255;
// Must comfortably exceed your slowest legitimate order creation.
const STALE_LOCK_SECONDS = 120;

// ---------- helpers ----------

function stableStringify(v: unknown): string {
  if (Array.isArray(v)) return `[${v.map(stableStringify).join(",")}]`;
  if (v && typeof v === "object") {
    const o = v as Record<string, unknown>;
    return `{${Object.keys(o)
      .sort()
      .map((k) => `${JSON.stringify(k)}:${stableStringify(o[k])}`)
      .join(",")}}`;
  }
  return JSON.stringify(v);
}

function hashRequest(req: Request): string {
  // Canonicalize so key order in the JSON body doesn't change the hash.
  return createHash("sha256")
    .update(`${req.method}\n${req.path}\n${stableStringify(req.body)}`)
    .digest("hex");
}

type Claim =
  | { kind: "acquired"; lockId: string }
  | { kind: "replay"; code: number; body: unknown }
  | { kind: "in_progress" }
  | { kind: "mismatch" };

// ---------- claim the key atomically ----------

async function claimKey(userId: string, key: string, hash: string): Promise<Claim> {
  const lockId = randomUUID();

  for (let i = 0; i < 3; i++) {
    // Autocommitted, so concurrent requests immediately see the in_progress row.
    const ins = await pool.query(
      `INSERT INTO idempotency_keys (user_id, key, request_hash, status, lock_id, locked_at)
       VALUES ($1, $2, $3, 'in_progress', $4, now())
       ON CONFLICT (user_id, key) DO NOTHING`,
      [userId, key, hash, lockId]
    );
    if (ins.rowCount === 1) return { kind: "acquired", lockId };

    const { rows } = await pool.query(
      `SELECT request_hash, status, response_code, response_body,
              (locked_at < now() - make_interval(secs => $3)) AS stale
       FROM idempotency_keys
       WHERE user_id = $1 AND key = $2`,
      [userId, key, STALE_LOCK_SECONDS]
    );

    // Row vanished (released or cleaned up) between INSERT and SELECT: try again.
    if (rows.length === 0) continue;

    const row = rows[0];
    if (row.request_hash !== hash) return { kind: "mismatch" };
    if (row.status === "completed") {
      return { kind: "replay", code: row.response_code, body: row.response_body };
    }

    if (row.stale) {
      // Previous owner likely crashed. Take over, but only if nobody else already has.
      const took = await pool.query(
        `UPDATE idempotency_keys
         SET lock_id = $3, locked_at = now()
         WHERE user_id = $1 AND key = $2
           AND status = 'in_progress'
           AND locked_at < now() - make_interval(secs => $4)`,
        [userId, key, lockId, STALE_LOCK_SECONDS]
      );
      if (took.rowCount === 1) return { kind: "acquired", lockId };
    }

    return { kind: "in_progress" };
  }

  return { kind: "in_progress" };
}

async function releaseKey(userId: string, key: string, lockId: string) {
  await pool.query(
    `DELETE FROM idempotency_keys
     WHERE user_id = $1 AND key = $2 AND lock_id = $3 AND status = 'in_progress'`,
    [userId, key, lockId]
  );
}

// ---------- the handler ----------

export async function createOrderHandler(req: Request, res: Response, next: NextFunction) {
  const key = req.header("Idempotency-Key");
  if (!key || key.length > MAX_KEY_LENGTH) {
    return res.status(400).json({
      error: `Idempotency-Key header is required (max ${MAX_KEY_LENGTH} chars)`,
    });
  }

  const userId: string = (req as any).user.id; // from your auth middleware
  const claim = await claimKey(userId, key, hashRequest(req));

  switch (claim.kind) {
    case "mismatch":
      return res.status(422).json({
        error: "Idempotency-Key was already used with a different request",
      });
    case "in_progress":
      return res
        .status(409)
        .set("Retry-After", "2")
        .json({ error: "A request with this Idempotency-Key is still in progress" });
    case "replay":
      return res.status(claim.code).set("Idempotent-Replayed", "true").json(claim.body);
  }

  // We own the key. Do the work and mark it completed in ONE transaction,
  // so the order and the stored response commit or roll back together.
  const { lockId } = claim;
  const client = await pool.connect();

  try {
    await client.query("BEGIN");

    const order = await createOrder(client, userId, req.body); // must use `client`
    const responseBody = { order };

    const done = await client.query(
      `UPDATE idempotency_keys
       SET status = 'completed', response_code = 201, response_body = $4
       WHERE user_id = $1 AND key = $2 AND lock_id = $3 AND status = 'in_progress'`,
      [userId, key, lockId, JSON.stringify(responseBody)]
    );

    if (done.rowCount !== 1) {
      // Our lock was taken over (we were too slow). Discard our work.
      await client.query("ROLLBACK");
      return res.status(409).json({ error: "Request superseded; retry" });
    }

    await client.query("COMMIT");
    return res.status(201).json(responseBody);
  } catch (err) {
    await client.query("ROLLBACK").catch(() => {});
    // Release so the client can retry with the same key. If this fails,
    // the stale-lock takeover covers it.
    await releaseKey(userId, key, lockId).catch(() => {});
    return next(err);
  } finally {
    client.release();
  }
}

// Your existing order logic, taking a transaction client.
declare function createOrder(
  client: import("pg").PoolClient,
  userId: string,
  input: unknown
): Promise<{ id: string }>;
```

## Behavior

| Situation | Response |
|---|---|
| First request | Runs, returns 201, response stored |
| Retry after completion | Stored response replayed, with `Idempotent-Replayed: true` |
| Retry while the original is still running | 409 with `Retry-After` |
| Same key, different body, path, or method | 422 |
| Original crashed and the lock is older than 120s | A retry takes over and runs |
| Request fails (validation error, exception) | Key released and error returned, so a corrected retry can reuse the key |

## Things to check

- **`createOrder` must use the passed `client`.** The safety of takeover depends on the order insert being in the same transaction as the key completion. If it uses the pool directly, a crash or lost lock can leave an order behind with no recorded key.
- **External side effects break that guarantee.** If order creation charges a card or calls another service, a rolled-back or taken-over attempt can't undo that call. Pass the same idempotency key (or one derived from it) downstream, so the other service dedupes too.
- **`STALE_LOCK_SECONDS` must exceed your slowest real request.** If it's too short, a slow but healthy request gets taken over. The `lock_id` check stops a double commit, but the slow request's work is thrown away and the client sees a 409.
- **Failures aren't cached.** Errors release the key instead of storing the error, which suits transient failures. Stripe caches deterministic 4xx results instead. If you want that, store the error in the `catch` branch rather than releasing.
- **Scoping by `user_id`** means two users can safely send the same key. If orders can be created unauthenticated, you'll need another scope, such as an API client ID.
- **Tests:** the cases most worth testing are two simultaneous requests with the same key (one 201, one 409 or replay), and a crash between claim and commit followed by a retry after the stale window.

I can write those tests if you want, for example with Jest, using `Promise.all` for the concurrency case.

