## Handler

```ts
import { createHash } from "node:crypto";
import type { Request, Response } from "express";
import { Pool, PoolClient } from "pg";

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Must be comfortably longer than your max request duration (incl. DB timeouts).
const STALE_AFTER = "2 minutes";

type Claim =
  | { kind: "owned" }
  | { kind: "replay"; code: number; body: unknown }
  | { kind: "mismatch" }
  | { kind: "conflict" };

function hashRequest(body: unknown): string {
  // Note: JSON.stringify depends on key order. Use a canonical/stable
  // stringify if clients might reorder fields between retries.
  return createHash("sha256").update(JSON.stringify(body)).digest("hex");
}

async function claimKey(userId: string, key: string, hash: string): Promise<Claim> {
  // 1. Try to insert. Exactly one concurrent request wins.
  const inserted = await pool.query(
    `INSERT INTO idempotency_keys (user_id, key, request_hash, status)
     VALUES ($1, $2, $3, 'in_progress')
     ON CONFLICT (user_id, key) DO NOTHING
     RETURNING 1`,
    [userId, key, hash]
  );
  if (inserted.rowCount === 1) return { kind: "owned" };

  // 2. Key already exists. Look at it.
  const { rows } = await pool.query(
    `SELECT request_hash, status, response_code, response_body
     FROM idempotency_keys WHERE user_id = $1 AND key = $2`,
    [userId, key]
  );
  const existing = rows[0];
  if (!existing) return claimKey(userId, key, hash); // deleted by cleanup/rollback in between; retry

  if (existing.request_hash !== hash) return { kind: "mismatch" };

  if (existing.status === "completed") {
    return { kind: "replay", code: existing.response_code, body: existing.response_body };
  }

  // 3. in_progress: take over only if the row looks abandoned. The conditional
  // UPDATE is atomic, so only one request can win the takeover.
  const takeover = await pool.query(
    `UPDATE idempotency_keys
     SET locked_at = now()
     WHERE user_id = $1 AND key = $2
       AND status = 'in_progress'
       AND locked_at < now() - $3::interval
     RETURNING 1`,
    [userId, key, STALE_AFTER]
  );
  return takeover.rowCount === 1 ? { kind: "owned" } : { kind: "conflict" };
}

async function insertOrder(client: PoolClient, userId: string, input: any) {
  // Your real order creation goes here. It MUST use `client` (the transaction).
  const { rows } = await client.query(
    `INSERT INTO orders (user_id, sku, qty) VALUES ($1, $2, $3) RETURNING *`,
    [userId, input.sku, input.qty]
  );
  return rows[0];
}

export async function createOrderHandler(req: Request, res: Response) {
  const key = req.header("Idempotency-Key");
  if (!key || key.length > 255) {
    return res.status(400).json({ error: "Idempotency-Key header required (max 255 chars)" });
  }

  const userId: string = (req as any).user.id; // from your auth middleware

  // Validate BEFORE claiming, so malformed requests don't burn keys.
  if (!req.body?.sku || !Number.isInteger(req.body?.qty) || req.body.qty < 1) {
    return res.status(400).json({ error: "Invalid order" });
  }

  const claim = await claimKey(userId, key, hashRequest(req.body));

  switch (claim.kind) {
    case "mismatch":
      return res.status(422).json({ error: "Idempotency-Key was already used with a different request" });
    case "conflict":
      return res.status(409).set("Retry-After", "1").json({ error: "A request with this key is still in progress" });
    case "replay":
      return res.status(claim.code).set("Idempotent-Replayed", "true").json(claim.body);
    case "owned":
      break;
  }

  // Create the order and mark the key completed in ONE transaction.
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const order = await insertOrder(client, userId, req.body);
    const responseBody = { order };
    await client.query(
      `UPDATE idempotency_keys
       SET status = 'completed', response_code = 201, response_body = $3
       WHERE user_id = $1 AND key = $2`,
      [userId, key, JSON.stringify(responseBody)]
    );
    await client.query("COMMIT");
    return res.status(201).json(responseBody);
  } catch (err) {
    await client.query("ROLLBACK").catch(() => {});
    // Release the key so the client's retry can run instead of waiting for takeover.
    await pool
      .query(
        `DELETE FROM idempotency_keys
         WHERE user_id = $1 AND key = $2 AND status = 'in_progress'`,
        [userId, key]
      )
      .catch(() => {}); // if this fails, the stale-takeover path covers it
    console.error("create order failed", err);
    return res.status(500).json({ error: "Internal error" });
  } finally {
    client.release();
  }
}
```

## Why it's built this way

- **The order and the "completed" marker commit together.** If the server crashes mid-request, the order is rolled back too, so letting a retry take over a stale row can't create a duplicate. If you create the order outside this transaction (for example by calling a payment API or another service), takeover becomes unsafe. You'd need to pass your own idempotency key downstream.
- **The claim is a separate, committed statement.** That lets concurrent duplicates see the `in_progress` row right away and get a 409 instead of blocking on a lock.
- **Only successes are stored.** Failures delete the key so the client can retry. If you'd rather replay deterministic 4xx results, store them as `completed` instead of deleting.
- **`STALE_AFTER` must exceed your longest possible request time.** Otherwise a slow-but-alive request could be taken over and processed twice. Set a statement or request timeout well below it.
- **Clients should treat 409 as "wait and retry with the same key."** The `postIdempotent` helper from earlier currently returns 409 to the caller. Add `res.status === 409` to its retryable statuses if you want it handled automatically.

