I'll continue with Express, Postgres, and `node-postgres`. I'm also assuming your auth middleware sets `req.user.id`, which scopes keys per user so one user can never replay another's response.

## Table definition

```sql
CREATE TABLE idempotency_keys (
  scope           text        NOT NULL,   -- e.g. user/account id
  key             text        NOT NULL,   -- value of the Idempotency-Key header
  request_hash    text        NOT NULL,   -- detects same key + different payload
  status          text        NOT NULL CHECK (status IN ('processing', 'completed')),
  lock_id         uuid        NOT NULL,   -- fencing token for the current owner
  locked_at       timestamptz NOT NULL DEFAULT now(),
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (scope, key),
  CHECK (status <> 'completed' OR response_status IS NOT NULL)
);

-- Used by the cleanup job
CREATE INDEX idx_idempotency_keys_created_at ON idempotency_keys (created_at);
```

## Handler logic

The wrapper takes a handler that *returns* `{ status, body }` instead of writing to `res`, so the response can be stored before it's sent.

```ts
// idempotent.ts
import { createHash, randomUUID } from "node:crypto";
import type { Request, RequestHandler } from "express";
import { Pool } from "pg";

const pool = new Pool();

const TTL = "24 hours";         // keep in sync with the cleanup job
const LOCK_TIMEOUT = "5 minutes"; // "processing" rows older than this are treated as abandoned

export type HandlerResult = { status: number; body: unknown };

const getScope = (req: Request): string => String((req as any).user.id);

function hashRequest(req: Request): string {
  return createHash("sha256")
    .update(`${req.method}\n${req.originalUrl}\n${JSON.stringify(req.body ?? null)}`)
    .digest("hex");
}

/**
 * Try to become the owner of this key. Succeeds if the key is new, expired,
 * or held by an abandoned "processing" row. Returns false otherwise.
 */
async function claim(scope: string, key: string, hash: string, lockId: string): Promise<boolean> {
  const { rowCount } = await pool.query(
    `INSERT INTO idempotency_keys (scope, key, request_hash, status, lock_id, locked_at)
     VALUES ($1, $2, $3, 'processing', $4, now())
     ON CONFLICT (scope, key) DO UPDATE
       SET request_hash    = EXCLUDED.request_hash,
           status          = 'processing',
           lock_id         = EXCLUDED.lock_id,
           locked_at       = now(),
           created_at      = now(),
           response_status = NULL,
           response_body   = NULL
       WHERE idempotency_keys.created_at < now() - $5::interval
          OR (idempotency_keys.status = 'processing'
              AND idempotency_keys.locked_at < now() - $6::interval)`,
    [scope, key, hash, lockId, TTL, LOCK_TIMEOUT]
  );
  return (rowCount ?? 0) > 0;
}

async function findExisting(scope: string, key: string) {
  const { rows } = await pool.query(
    `SELECT request_hash, status, response_status, response_body
     FROM idempotency_keys WHERE scope = $1 AND key = $2`,
    [scope, key]
  );
  return rows[0] as
    | { request_hash: string; status: string; response_status: number | null; response_body: unknown }
    | undefined;
}

async function complete(scope: string, key: string, lockId: string, r: HandlerResult) {
  const { rowCount } = await pool.query(
    `UPDATE idempotency_keys
     SET status = 'completed', response_status = $4, response_body = $5::jsonb
     WHERE scope = $1 AND key = $2 AND lock_id = $3`,
    [scope, key, lockId, r.status, JSON.stringify(r.body ?? null)]
  );
  if (rowCount === 0) console.warn("Lost idempotency claim before completing", { scope, key });
}

async function release(scope: string, key: string, lockId: string) {
  await pool.query(
    `DELETE FROM idempotency_keys WHERE scope = $1 AND key = $2 AND lock_id = $3`,
    [scope, key, lockId]
  );
}

export function idempotent(handler: (req: Request) => Promise<HandlerResult>): RequestHandler {
  return async (req, res, next) => {
    try {
      const key = req.header("Idempotency-Key");
      if (!key || key.length > 255) {
        return res.status(400).json({ error: "Idempotency-Key header is required (max 255 chars)" });
      }

      const scope = getScope(req);
      const hash = hashRequest(req);
      const lockId = randomUUID();

      for (let attempt = 0; attempt < 3; attempt++) {
        if (await claim(scope, key, hash, lockId)) {
          // We own the key: run the handler exactly once.
          let result: HandlerResult;
          try {
            result = await handler(req);
          } catch (err) {
            await release(scope, key, lockId).catch(() => {});
            throw err;
          }

          if (result.status >= 500) {
            // Server errors are not cached; let the client retry for real.
            await release(scope, key, lockId).catch(() => {});
          } else {
            await complete(scope, key, lockId, result);
          }
          return res.status(result.status).json(result.body);
        }

        const existing = await findExisting(scope, key);
        if (!existing) continue; // released or cleaned up between the two queries; try again

        if (existing.request_hash !== hash) {
          return res.status(422).json({
            error: "Idempotency-Key was already used with a different request",
          });
        }

        if (existing.status === "completed") {
          res.set("Idempotent-Replayed", "true");
          return res.status(existing.response_status!).json(existing.response_body);
        }

        // Same request still in flight
        res.set("Retry-After", "2");
        return res.status(409).json({ error: "A request with this Idempotency-Key is still in progress" });
      }

      res.set("Retry-After", "1");
      return res.status(409).json({ error: "Could not acquire idempotency key, retry" });
    } catch (err) {
      next(err);
    }
  };
}
```

Wiring it to the order route:

```ts
app.post(
  "/api/orders",
  express.json(),
  requireAuth,
  idempotent(async (req) => {
    const order = await createOrder(req.body, (req as any).user.id);
    return { status: 201, body: order };
  })
);
```

## How it behaves

| Situation | Result |
|---|---|
| New key | Handler runs, response stored |
| Same key, same payload, completed | Stored response replayed with `Idempotent-Replayed: true` |
| Same key, same payload, still running | `409` + `Retry-After` |
| Same key, different payload | `422` |
| Handler throws or returns 5xx | Key released, so a retry re-executes |
| 2xx/4xx result | Stored and replayed, so a validation `400` replays as a `400` |
| Key older than 24h | Treated as absent and overwritten, regardless of whether cleanup has run |

The `lock_id` fencing token means that if a slow request is taken over after the 5-minute timeout, the original can't overwrite the new owner's result when it finally finishes.

## Limitations

- **A crash between order creation and `complete()` can still produce a duplicate.** If the order commits but the process dies (or the DB write fails) before the response is saved, the row stays `processing`. After 5 minutes a retry takes over and creates a second order. If order creation is purely database work, you can close this gap by running the claim, the order insert, and the `complete` update in one transaction. A concurrent duplicate then simply blocks on the row until the first commits. If order creation calls a payment provider, pass the provider its own idempotency key derived from this one.
- **`LOCK_TIMEOUT` must exceed your slowest legitimate request.** If it's shorter, a slow but healthy request gets taken over and duplicated.
- **The payload hash is order-sensitive.** `JSON.stringify` of the parsed body treats `{a,b}` and `{b,a}` as different. That's fine when clients retry with identical bytes, as the helper from earlier does. If you need more tolerance, hash a canonicalized form or only the fields that define the order.
- **Test the concurrent case.** Fire two identical requests at once, for example with `Promise.all`, and confirm that exactly one order is created and the other gets a `409` or a replay. That's the scenario this exists for.

I can write that concurrency test or the single-transaction variant next if you'd like.

