```python
import json
import logging
import time
import uuid
from concurrent.futures import ThreadPoolExecutor
from typing import Any, Callable

import redis

from jitter import jittered_expiry

log = logging.getLogger(__name__)

# Delete the lock only if we still own it (the token matches).
_RELEASE_LOCK = """
if redis.call('get', KEYS[1]) == ARGV[1] then
  return redis.call('del', KEYS[1])
end
return 0
"""


class SWRCache:
    def __init__(
        self,
        client: redis.Redis,  # create with decode_responses=True
        ttl_seconds: float = 3600,
        jitter_ratio: float = 0.3,
        stale_multiplier: float = 3.0,
        lock_ttl: int = 30,
        cold_wait: float = 2.0,
        max_workers: int = 4,
        prefix: str = "cache:",
    ):
        self.r = client
        self.ttl = ttl_seconds
        self.jitter_ratio = jitter_ratio
        self.stale_multiplier = stale_multiplier
        self.lock_ttl = lock_ttl
        self.cold_wait = cold_wait
        self.prefix = prefix
        self._release = client.register_script(_RELEASE_LOCK)
        self._pool = ThreadPoolExecutor(
            max_workers=max_workers, thread_name_prefix="swr-refresh"
        )

    def get(self, key: str, loader: Callable[[], Any], ttl_seconds: float | None = None) -> Any:
        rkey = self.prefix + key
        ttl = ttl_seconds or self.ttl

        try:
            entry = self._read(rkey)
        except redis.RedisError:
            log.warning("redis read failed for %s; bypassing cache", rkey)
            return loader()

        if entry is None:
            return self._load_cold(rkey, loader, ttl)

        if time.time() >= entry["fresh_until"]:
            self._refresh_async(rkey, loader, ttl)
        return entry["value"]

    # --- internals ---

    def _read(self, rkey: str) -> dict | None:
        raw = self.r.get(rkey)
        return json.loads(raw) if raw is not None else None

    def _fill(self, rkey: str, loader: Callable[[], Any], ttl: float) -> Any:
        value = loader()
        fresh_until, redis_ttl = jittered_expiry(
            ttl, self.jitter_ratio, self.stale_multiplier
        )
        try:
            self.r.set(
                rkey,
                json.dumps({"value": value, "fresh_until": fresh_until}),
                ex=redis_ttl,
            )
        except redis.RedisError:
            log.warning("redis write failed for %s", rkey)
        return value

    def _acquire(self, rkey: str) -> str | None:
        token = uuid.uuid4().hex
        ok = self.r.set(rkey + ":lock", token, nx=True, ex=self.lock_ttl)
        return token if ok else None

    def _unlock(self, rkey: str, token: str) -> None:
        try:
            self._release(keys=[rkey + ":lock"], args=[token])
        except redis.RedisError:
            pass  # lock expires on its own

    def _load_cold(self, rkey: str, loader: Callable[[], Any], ttl: float) -> Any:
        """No entry at all: one caller loads, the others wait briefly for it."""
        try:
            token = self._acquire(rkey)
        except redis.RedisError:
            return loader()

        if token is None:
            deadline = time.monotonic() + self.cold_wait
            while time.monotonic() < deadline:
                time.sleep(0.05)
                try:
                    entry = self._read(rkey)
                except redis.RedisError:
                    break
                if entry is not None:
                    return entry["value"]
            return self._fill(rkey, loader, ttl)  # loader is slow or failed; don't hang

        try:
            entry = self._read(rkey)  # someone may have filled it while we acquired
            if entry is not None:
                return entry["value"]
            return self._fill(rkey, loader, ttl)
        finally:
            self._unlock(rkey, token)

    def _refresh_async(self, rkey: str, loader: Callable[[], Any], ttl: float) -> None:
        try:
            token = self._acquire(rkey)
        except redis.RedisError:
            return
        if token is None:
            return  # another worker is already refreshing this key
        try:
            self._pool.submit(self._refresh, rkey, loader, ttl, token)
        except RuntimeError:  # pool already shut down
            self._unlock(rkey, token)

    def _refresh(self, rkey: str, loader: Callable[[], Any], ttl: float, token: str) -> None:
        try:
            self._fill(rkey, loader, ttl)
        except Exception:
            # Leave the lock to expire so a failing backend isn't retried on every request.
            log.exception("background refresh failed for %s; still serving stale", rkey)
            return
        self._unlock(rkey, token)

    def close(self) -> None:
        self._pool.shutdown(wait=False)
