Your request doesn't say how refresh should work, what the wrapper returns, or how big its scope is, and those choices shape the interface. I've picked defaults you can change:

- **Refresh:** the caller passes a `loader` function per call. The wrapper runs it in a background thread when it serves a stale entry.
- **Return value:** `get()` returns just the value. `get_result()` also returns a `stale` flag if the caller wants it.
- **Scope:** one wrapper around one Redis client, with per-key locks and soft-expiry metadata. It is not a full cache manager.

It uses `jittered_expiry` from the previous step.

```python
import json
import logging
import time
import uuid
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass
from typing import Any, Callable

log = logging.getLogger(__name__)

# Delete the lock only if we still own it.
_RELEASE_LOCK = """
if redis.call('get', KEYS[1]) == ARGV[1] then
    return redis.call('del', KEYS[1])
end
return 0
"""


@dataclass(frozen=True)
class CacheResult:
    value: Any
    stale: bool  # True if served past soft expiry (a refresh was triggered)
    hit: bool    # False if the value came from a blocking load


class SWRCache:
    def __init__(
        self,
        redis_client,
        *,
        ttl: float = 300,
        stale_window: float = 3600,
        jitter: float = 0.2,
        lock_ttl: int = 30,
        cold_wait: float = 2.0,
        prefix: str = "cache:",
        max_workers: int = 8,
    ):
        self.r = redis_client
        self.ttl = ttl
        self.stale_window = stale_window
        self.jitter = jitter
        self.lock_ttl = lock_ttl
        self.cold_wait = cold_wait
        self.prefix = prefix
        self._pool = ThreadPoolExecutor(max_workers=max_workers, thread_name_prefix="swr-refresh")
        self._release = self.r.register_script(_RELEASE_LOCK)

    # ---- public API ----

    def get(self, key: str, loader: Callable[[], Any], **opts) -> Any:
        return self.get_result(key, loader, **opts).value

    def get_result(self, key: str, loader: Callable[[], Any], **opts) -> CacheResult:
        try:
            raw = self.r.get(self._k(key))
        except Exception:
            log.exception("cache read failed; loading directly")
            return CacheResult(loader(), stale=False, hit=False)

        if raw is None:
            return self._cold_load(key, loader, opts)

        entry = json.loads(raw)
        if time.time() < entry["soft_exp"]:
            return CacheResult(entry["v"], stale=False, hit=True)

        # Stale: serve it now, refresh in the background (one refresher per key).
        self._maybe_refresh(key, loader, opts)
        return CacheResult(entry["v"], stale=True, hit=True)

    def invalidate(self, key: str) -> None:
        self.r.delete(self._k(key))

    def close(self) -> None:
        self._pool.shutdown(wait=False)

    # ---- internals ----

    def _k(self, key: str) -> str:
        return f"{self.prefix}{key}"

    def _lock_key(self, key: str) -> str:
        return f"{self.prefix}{key}:lock"

    def _acquire(self, key: str) -> str | None:
        token = uuid.uuid4().hex
        try:
            ok = self.r.set(self._lock_key(key), token, nx=True, ex=self.lock_ttl)
        except Exception:
            log.exception("lock acquire failed")
            return None
        return token if ok else None

    def _store(self, key: str, value: Any, opts: dict) -> None:
        # jittered_expiry is the helper from the previous step
        exp = jittered_expiry(
            opts.get("ttl", self.ttl),
            opts.get("stale_window", self.stale_window),
            opts.get("jitter", self.jitter),
        )
        payload = json.dumps({"v": value, "soft_exp": exp.soft_expires_at})
        self.r.set(self._k(key), payload, ex=exp.physical_ttl)

    def _cold_load(self, key: str, loader, opts) -> CacheResult:
        token = self._acquire(key)
        if token:
            try:
                value = loader()
                self._safe_store(key, value, opts)
                return CacheResult(value, stale=False, hit=False)
            finally:
                self._release(keys=[self._lock_key(key)], args=[token])

        # Someone else is loading: wait briefly for their result.
        deadline = time.monotonic() + self.cold_wait
        while time.monotonic() < deadline:
            time.sleep(0.05)
            try:
                raw = self.r.get(self._k(key))
            except Exception:
                break
            if raw is not None:
                return CacheResult(json.loads(raw)["v"], stale=False, hit=True)

        # Loader is slow or failed; don't hang the request.
        return CacheResult(loader(), stale=False, hit=False)

    def _maybe_refresh(self, key: str, loader, opts) -> None:
        token = self._acquire(key)
        if not token:
            return  # another worker is already refreshing
        try:
            self._pool.submit(self._refresh, key, loader, opts, token)
        except Exception:
            self._release(keys=[self._lock_key(key)], args=[token])
            raise

    def _refresh(self, key: str, loader, opts, token: str) -> None:
        try:
            value = loader()
            self._store(key, value, opts)
        except Exception:
            # Keep the lock until it expires: that acts as a retry backoff
            # so a failing loader isn't hammered. Stale data keeps being served.
            log.exception("background refresh failed for %s", key)
            return
        self._release(keys=[self._lock_key(key)], args=[token])

    def _safe_store(self, key: str, value: Any, opts: dict) -> None:
        try:
            self._store(key, value, opts)
        except Exception:
            log.exception("cache write failed for %s", key)
```

