```js
// routes/passwordResetRequest.js
const crypto = require('node:crypto');
const express = require('express');
const rateLimit = require('express-rate-limit');
const { pool } = require('../db');
const { sendEmail } = require('../mailer');            // your SES/SendGrid/SMTP wrapper
const { renderResetEmail } = require('../emails/resetPassword');
const config = require('../config');                   // { appBaseUrl, appName, supportEmail, ... }

const router = express.Router();

const TOKEN_TTL_MINUTES = 30;                          // single source of truth, also used in the email
const MAX_REQUESTS_PER_USER_PER_HOUR = 3;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const GENERIC_RESPONSE = {
  message: 'If an account exists for that email, a reset link is on its way.',
};

// Per-IP throttle. Requires `app.set('trust proxy', ...)` if behind a load balancer,
// otherwise every request appears to come from the proxy's IP.
const ipLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 10,
  standardHeaders: true,
  legacyHeaders: false,
  message: { message: 'Too many requests. Please try again later.' },
});

router.post(
  '/password-reset/request',
  ipLimiter,
  express.json({ limit: '1kb' }),
  async (req, res) => {
    const raw = req.body?.email;
    const email = typeof raw === 'string' ? raw.trim().toLowerCase() : '';

    // Malformed input can be rejected without leaking anything about accounts.
    if (email.length > 254 || !EMAIL_RE.test(email)) {
      return res.status(400).json({ message: 'Please enter a valid email address.' });
    }

    // Respond first, then do the work. Response time is then identical whether or
    // not the account exists, which closes the timing side channel on enumeration.
    res.set('Cache-Control', 'no-store');
    res.status(202).json(GENERIC_RESPONSE);

    try {
      await issueResetToken({
        email,
        ip: req.ip,
        userAgent: (req.get('user-agent') || '').slice(0, 255),
      });
    } catch (err) {
      // Never surface this to the client. Log without the email or token.
      console.error('password reset issuance failed', { error: err.message });
    }
  }
);

async function issueResetToken({ email, ip, userAgent }) {
  const rawToken = crypto.randomBytes(32).toString('base64url');
  const tokenHash = crypto.createHash('sha256').update(rawToken).digest('hex');

  const client = await pool.connect();
  let user;

  try {
    await client.query('BEGIN');

    // Lock the user row so concurrent requests serialize on the throttle check.
    // Add `AND disabled_at IS NULL` (or similar) if you have suspended accounts.
    const { rows } = await client.query(
      `SELECT id, email, first_name
         FROM users
        WHERE lower(email) = $1
        FOR UPDATE`,
      [email]
    );
    user = rows[0];

    if (!user) {
      await client.query('ROLLBACK');
      return; // unknown email: do nothing
    }

    // Per-account throttle to prevent email bombing. Silently skip when exceeded.
    const { rows: recent } = await client.query(
      `SELECT count(*)::int AS n
         FROM password_reset_tokens
        WHERE user_id = $1 AND created_at > now() - interval '1 hour'`,
      [user.id]
    );
    if (recent[0].n >= MAX_REQUESTS_PER_USER_PER_HOUR) {
      await client.query('ROLLBACK');
      return;
    }

    // Only the newest link should work.
    await client.query(
      `UPDATE password_reset_tokens
          SET used_at = now()
        WHERE user_id = $1 AND used_at IS NULL`,
      [user.id]
    );

    await client.query(
      `INSERT INTO password_reset_tokens
         (user_id, token_hash, expires_at, requested_ip, user_agent)
       VALUES ($1, $2, now() + make_interval(mins => $3), $4, $5)`,
      [user.id, tokenHash, TOKEN_TTL_MINUTES, ip, userAgent]
    );

    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    throw err;
  } finally {
    client.release();
  }

  // Send only after the token is committed, so a link never exists without a valid row.
  const resetUrl = `${config.appBaseUrl}/reset-password?token=${rawToken}`;
  const { subject, text, html } = renderResetEmail({
    app_name: config.appName,
    first_name: user.first_name || 'there',
    reset_url: resetUrl,
    expiry_minutes: TOKEN_TTL_MINUTES,
    support_email: config.supportEmail,
    support_url: config.supportUrl,
    company_address: config.companyAddress,
    requested_at_utc: new Date().toISOString().replace('T', ' ').slice(0, 16),
  });

  await sendEmail({ to: user.email, subject, text, html });
}

module.exports = router;
```

