app.put("/paragraphs/:id", async (req, res) => {
  const { content, base_version } = req.body;
  if (!Number.isInteger(base_version)) {
    return res.status(400).json({
      error: { code: "missing_base_version", message: "base_version is required." },
    });
  }

  const updated = await db.query(
    `UPDATE paragraphs
     SET content = $1, version = version + 1, updated_at = now()
     WHERE id = $2 AND version = $3
     RETURNING id, content, version, updated_at`,
    [content, req.params.id, base_version]
  );
  if (updated.rowCount === 1) return res.json(updated.rows[0]);

  const current = await db.query(
    `SELECT content, version, updated_at, updated_by
     FROM paragraphs WHERE id = $1`,
    [req.params.id]
  );
  if (current.rowCount === 0) {
    return res.status(404).json({
      error: { code: "not_found", message: "Paragraph no longer exists." },
    });
  }

  return res.status(409).json({
    error: {
      code: "version_conflict",
      message: "This paragraph was changed by someone else since you loaded it.",
    },
    paragraph_id: req.params.id,
    submitted: { base_version, content },
    current: current.rows[0],
  });
});
```

