import express from "express";
import { Pool } from "pg";

const db = new Pool(); // configured via PG* env vars

app.put("/paragraphs/:id", async (req, res) => {
  const { id } = req.params;
  const { content, base_version } = req.body ?? {};
  const userId = req.user.id; // assumes auth middleware populates req.user

  if (typeof content !== "string") {
    return res.status(400).json({
      error: { code: "invalid_content", message: "content must be a string." },
    });
  }
  if (!Number.isInteger(base_version) || base_version < 1) {
    return res.status(400).json({
      error: { code: "missing_base_version", message: "base_version is required." },
    });
  }

  try {
    // Atomic check-and-write: only succeeds if the version still matches.
    const updated = await db.query(
      `UPDATE paragraphs
       SET content = $1,
           version = version + 1,
           updated_at = now(),
           updated_by = $2
       WHERE id = $3 AND version = $4
       RETURNING id, content, version, updated_at`,
      [content, userId, id, base_version]
    );
    if (updated.rowCount === 1) {
      return res.status(200).json(updated.rows[0]);
    }

    // 0 rows: either the paragraph is gone or the version was stale.
    const current = await db.query(
      `SELECT id, content, version, updated_at, updated_by
       FROM paragraphs WHERE id = $1`,
      [id]
    );
    if (current.rowCount === 0) {
      return res.status(404).json({
        error: { code: "not_found", message: "Paragraph no longer exists." },
      });
    }

    const row = current.rows[0];

    // Retry safety: if the client's first attempt succeeded but the response
    // was lost, the retry looks stale. If the stored content already equals
    // what was submitted, there is nothing to merge, so report success.
    if (row.content === content) {
      return res.status(200).json({
        id: row.id,
        content: row.content,
        version: row.version,
        updated_at: row.updated_at,
      });
    }

    return res.status(409).json({
      error: {
        code: "version_conflict",
        message: "This paragraph was changed by someone else since you loaded it.",
      },
      paragraph_id: id,
      submitted: { base_version, content },
      current: {
        version: row.version,
        content: row.content,
        updated_at: row.updated_at,
        updated_by: row.updated_by,
      },
    });
  } catch (err) {
    console.error("save paragraph failed", err);
    return res.status(500).json({
      error: { code: "internal_error", message: "Could not save. Please retry." },
    });
  }
});
```

**What changed from the sketch**
- **`try/catch`:** Express 4 doesn't catch rejected promises in async handlers, so a DB error would otherwise hang the request.
- **Input validation:** `content` must be a string and `base_version` a positive integer.
- **`updated_by`:** it's written on every save, so the 409 body can say who made the conflicting change.
- **Same-content shortcut:** it returns 200 instead of 409 when the stored content already matches the submission. This covers a retry after a dropped response, and also two users who made the identical edit. Remove it if you want strict "version mismatch always means 409" behavior.

**Things to be aware of**
- **Authorization:** I didn't add a permission check. You need one, ideally in the `WHERE` clause or in middleware, so a conflict response doesn't leak the content of a paragraph the user can't access.
- **Concurrent writers:** under Postgres's default READ COMMITTED isolation, two simultaneous saves with the same `base_version` are safe. The second `UPDATE` waits for the first to commit, re-checks `version`, matches 0 rows, and gets the 409.
- **Other write paths:** imports, background jobs, and any other endpoint that updates `paragraphs.content` must use the same `WHERE version = ...` pattern and bump the version. One path that skips it brings back the lost edits.

