Here's a small TypeScript helper. It wraps `localStorage` defensively, since access can throw (private mode, disabled storage, quota exceeded) and stored data can be corrupt.

```ts
const KEY_PREFIX = "draft:v1:";

export interface Draft {
  docId: string;
  content: string;
  savedAt: number;                       // epoch ms
  baseRevision?: string | number | null; // server revision the draft was based on
}

const draftKey = (docId: string) => `${KEY_PREFIX}${docId}`;

function getStorage(): Storage | null {
  try {
    return typeof window !== "undefined" ? window.localStorage : null;
  } catch {
    return null; // access can throw when storage is blocked
  }
}

/** Saves a draft. Returns true on success, false if it couldn't be written. */
export function saveDraft(
  docId: string,
  content: string,
  baseRevision?: string | number | null
): boolean {
  const storage = getStorage();
  if (!storage) return false;

  const draft: Draft = { docId, content, savedAt: Date.now(), baseRevision };
  try {
    storage.setItem(draftKey(docId), JSON.stringify(draft));
    return true;
  } catch (err) {
    // Most likely QuotaExceededError
    console.warn(`Failed to save draft for ${docId}`, err);
    return false;
  }
}

/** Returns the stored draft, or null if none exists or it's unreadable. */
export function loadDraft(docId: string): Draft | null {
  const storage = getStorage();
  if (!storage) return null;

  try {
    const raw = storage.getItem(draftKey(docId));
    if (!raw) return null;

    const parsed = JSON.parse(raw) as Partial<Draft>;
    if (
      typeof parsed?.content !== "string" ||
      typeof parsed?.savedAt !== "number"
    ) {
      storage.removeItem(draftKey(docId)); // discard malformed data
      return null;
    }
    return {
      docId,
      content: parsed.content,
      savedAt: parsed.savedAt,
      baseRevision: parsed.baseRevision ?? null,
    };
  } catch {
    return null;
  }
}

/** Removes the draft, e.g. after a successful save to the server. */
export function clearDraft(docId: string): void {
  try {
    getStorage()?.removeItem(draftKey(docId));
  } catch {
    /* ignore */
  }
}
```

A few design notes:

- **`baseRevision`**: This is optional, but I'd recommend using it. When the user reopens a document, comparing the draft's base revision to the server's current one tells you whether the draft is safe to restore silently or whether you need to ask the user about a conflict.
- **`savedAt`**: This lets you show "Restore draft from 2:14 PM?" and compare against the server's last-modified time.
- **Versioned prefix (`v1`)**: If you later change the draft shape, you can migrate or ignore old entries without crashing.
- **Return value of `saveDraft`**: The autosave loop can use this to show a "couldn't save locally" warning rather than failing silently, which matters when the whole point is preventing lost edits.

