Here's the hook. It works in local-only mode, and it also takes an optional `saveToServer` callback. Without that callback, the draft lives only in this browser, which won't help a user who switches devices or clears site data. I'd treat server saving as the real fix and the local draft as the safety net.

```tsx
import { useCallback, useEffect, useRef, useState } from "react";
import { saveDraft, clearDraft } from "./drafts";
import type { SaveStatus } from "./SaveIndicator";

type Revision = string | number | null;

export interface UseAutosaveOptions {
  docId: string;
  /** Current editor content. */
  content: string;
  /** What the server has right now. Defaults to `content` at mount.
   *  Pass it explicitly if you restored a draft into the editor, otherwise
   *  the restored text will be treated as already saved. */
  serverContent?: string;
  baseRevision?: Revision;
  /** Persist to your backend. Throw/reject on failure. */
  saveToServer?: (
    content: string
  ) => Promise<{ revision?: Revision } | void>;
  intervalMs?: number;
  enabled?: boolean;
}

export interface UseAutosaveResult {
  status: SaveStatus;
  savedAt: number | null;
  target: "local" | "server";
  /** Run a save immediately, e.g. on blur or a Ctrl+S handler. */
  saveNow: () => Promise<void>;
}

export function useAutosave({
  docId,
  content,
  serverContent,
  baseRevision = null,
  saveToServer,
  intervalMs = 5000,
  enabled = true,
}: UseAutosaveOptions): UseAutosaveResult {
  const [status, setStatus] = useState<SaveStatus>("idle");
  const [savedAt, setSavedAt] = useState<number | null>(null);
  const [target, setTarget] = useState<"local" | "server">(
    saveToServer ? "server" : "local"
  );

  // Latest values, readable from timers and event handlers.
  const contentRef = useRef(content);
  const docIdRef = useRef(docId);
  const revisionRef = useRef<Revision>(baseRevision);
  const saveToServerRef = useRef(saveToServer);
  contentRef.current = content;
  docIdRef.current = docId;
  saveToServerRef.current = saveToServer;

  // Last content known to be persisted in each place.
  const lastLocalRef = useRef(serverContent ?? content);
  const lastServerRef = useRef(serverContent ?? content);
  const inFlightRef = useRef(false);

  // Reset when switching documents.
  useEffect(() => {
    lastLocalRef.current = serverContent ?? contentRef.current;
    lastServerRef.current = serverContent ?? contentRef.current;
    revisionRef.current = baseRevision;
    inFlightRef.current = false;
    setStatus("idle");
    setSavedAt(null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [docId]);

  // Mark dirty when content diverges from what's persisted.
  useEffect(() => {
    const persisted = saveToServerRef.current
      ? lastServerRef.current
      : lastLocalRef.current;
    if (content !== persisted) {
      setStatus((s) => (s === "idle" || s === "saved" ? "dirty" : s));
    }
  }, [content]);

  const save = useCallback(async () => {
    const id = docIdRef.current;
    const snapshot = contentRef.current;
    const server = saveToServerRef.current;

    // 1. Local draft: synchronous and cheap, so always do it first.
    let localOk = true;
    if (snapshot !== lastLocalRef.current) {
      localOk = saveDraft(id, snapshot, revisionRef.current);
      if (localOk) lastLocalRef.current = snapshot;
    }

    // 2. Server save, if configured and needed.
    if (server && snapshot !== lastServerRef.current) {
      if (inFlightRef.current) return; // don't overlap requests
      inFlightRef.current = true;
      setStatus("saving");
      try {
        const result = await server(snapshot);
        if (docIdRef.current !== id) return; // user switched docs mid-flight

        lastServerRef.current = snapshot;
        if (result && result.revision !== undefined) {
          revisionRef.current = result.revision;
        }
        const movedOn = contentRef.current !== snapshot;
        // Only drop the draft if nothing newer is waiting behind it.
        if (!movedOn) clearDraft(id);
        setTarget("server");
        setSavedAt(Date.now());
        setStatus(movedOn ? "dirty" : "saved");
      } catch (err) {
        console.warn(`Server save failed for ${id}`, err);
        if (docIdRef.current === id) {
          // Draft stays in place; the next tick retries.
          setTarget("server");
          setStatus("error");
        }
      } finally {
        inFlightRef.current = false;
      }
      return;
    }

    // Local-only path (or nothing new for the server).
    if (!server) {
      if (localOk) {
        setTarget("local");
        setSavedAt(Date.now());
        setStatus(contentRef.current === snapshot ? "saved" : "dirty");
      } else {
        setTarget("local");
        setStatus("error");
      }
    }
  }, []);

  // The 5-second loop. `save` is stable, so the interval isn't reset on keystrokes.
  useEffect(() => {
    if (!enabled) return;
    const id = setInterval(() => void save(), intervalMs);
    return () => clearInterval(id);
  }, [enabled, intervalMs, save]);

  // Flush the local draft when the tab is hidden or closing, and on unmount.
  // localStorage is synchronous, so it works in these handlers (a fetch might not).
  useEffect(() => {
    if (!enabled) return;

    const flushLocal = () => {
      const snapshot = contentRef.current;
      const persisted = saveToServerRef.current
        ? lastServerRef.current
        : lastLocalRef.current;
      if (snapshot !== persisted && snapshot !== lastLocalRef.current) {
        if (saveDraft(docIdRef.current, snapshot, revisionRef.current)) {
          lastLocalRef.current = snapshot;
        }
      }
    };
    const onVisibility = () => {
      if (document.visibilityState === "hidden") flushLocal();
    };

    document.addEventListener("visibilitychange", onVisibility);
    window.addEventListener("pagehide", flushLocal);
    return () => {
      document.removeEventListener("visibilitychange", onVisibility);
      window.removeEventListener("pagehide", flushLocal);
      flushLocal();
    };
  }, [enabled]);

  return { status, savedAt, target, saveNow: save };
}
```

