```tsx
import { useCallback, useEffect, useRef, useState } from "react";
import { clearDraft, loadDraft, saveDraft, type Draft } from "./draftStorage";
import type { SaveStatus } from "./SaveIndicator";

type Revision = string | number | null;

export interface UseAutosaveOptions {
  docId: string;
  /** Current editor content (controlled). */
  content: string;
  /** Content as last loaded from the server. */
  serverContent: string;
  /** Revision of serverContent. */
  serverRevision: Revision;
  intervalMs?: number; // default 5000
  /** Optional. If omitted, the hook only keeps a local draft. */
  saveToServer?: (
    content: string,
    baseRevision: Revision
  ) => Promise<{ revision: Revision }>;
}

export interface Recovery {
  draft: Draft;
  /** True if the server has moved on since this draft was started. */
  conflict: boolean;
}

export function useAutosave(opts: UseAutosaveOptions) {
  const { docId, intervalMs = 5000 } = opts;

  const [status, setStatus] = useState<SaveStatus>("idle");
  const [savedAt, setSavedAt] = useState<number | null>(null);
  const [target, setTarget] = useState<"local" | "server">("local");
  const [recovery, setRecovery] = useState<Recovery | null>(null);

  // Always-current copy of props, so the interval never needs to restart.
  const latest = useRef(opts);
  latest.current = opts;
  const paused = useRef(false);

  const lastSaved = useRef(opts.serverContent);
  const revision = useRef<Revision>(opts.serverRevision);
  const inFlight = useRef(false);

  // On document open: look for a leftover draft.
  useEffect(() => {
    const { serverContent, serverRevision } = latest.current;
    lastSaved.current = serverContent;
    revision.current = serverRevision;
    setStatus("idle");
    setSavedAt(null);

    const draft = loadDraft(docId);
    if (draft && draft.content !== serverContent) {
      const conflict =
        draft.baseRevision != null &&
        serverRevision != null &&
        draft.baseRevision !== serverRevision;
      paused.current = true; // don't overwrite the draft until the user decides
      setRecovery({ draft, conflict });
    } else {
      paused.current = false;
      setRecovery(null);
      if (draft) clearDraft(docId); // identical to server; stale
    }
  }, [docId]);

  // Mark dirty as soon as content diverges.
  useEffect(() => {
    if (paused.current || inFlight.current) return;
    if (opts.content !== lastSaved.current) setStatus("dirty");
  }, [opts.content]);

  const runSave = useCallback(async () => {
    const { docId, content, saveToServer } = latest.current;
    if (paused.current || content === lastSaved.current) return;

    // Local draft first: cheap, and protects against a failed network call.
    const localOk = saveDraft(docId, content, revision.current);

    if (!saveToServer) {
      if (localOk) lastSaved.current = content;
      setTarget("local");
      setStatus(localOk ? "saved" : "error");
      if (localOk) setSavedAt(Date.now());
      return;
    }

    if (inFlight.current) return;
    inFlight.current = true;
    setStatus("saving");
    try {
      const res = await saveToServer(content, revision.current);
      revision.current = res.revision;
      lastSaved.current = content;
      // Only drop the draft if nothing was typed during the request.
      if (latest.current.content === content) clearDraft(docId);
      setTarget("server");
      setStatus("saved");
      setSavedAt(Date.now());
    } catch {
      // Not recorded in lastSaved, so the next tick retries.
      setTarget(localOk ? "local" : "server");
      setStatus(localOk ? "saved" : "error");
      if (localOk) setSavedAt(Date.now());
    } finally {
      inFlight.current = false;
    }
  }, []);

  // The autosave tick.
  useEffect(() => {
    const id = setInterval(runSave, intervalMs);
    return () => clearInterval(id);
  }, [runSave, intervalMs]);

  // Flush the local draft when the tab is hidden or closing, rather than
  // waiting for the next tick. (Async server calls aren't reliable here.)
  useEffect(() => {
    const flushLocal = () => {
      const { docId, content } = latest.current;
      if (!paused.current && content !== lastSaved.current) {
        saveDraft(docId, content, revision.current);
      }
    };
    const onVisibility = () => {
      if (document.visibilityState === "hidden") flushLocal();
    };
    document.addEventListener("visibilitychange", onVisibility);
    window.addEventListener("pagehide", flushLocal);
    return () => {
      document.removeEventListener("visibilitychange", onVisibility);
      window.removeEventListener("pagehide", flushLocal);
    };
  }, []);

  /** Returns the draft content for you to put into the editor. */
  const restoreDraft = useCallback((): string | null => {
    if (!recovery) return null;
    paused.current = false;
    setRecovery(null);
    setStatus("dirty"); // next tick saves it against the current revision
    return recovery.draft.content;
  }, [recovery]);

  const discardDraft = useCallback(() => {
    clearDraft(latest.current.docId);
    paused.current = false;
    setRecovery(null);
  }, []);

  return {
    status,
    savedAt,
    target,
    recovery,
    restoreDraft,
    discardDraft,
    saveNow: runSave,
  };
}
```

Usage:

```tsx
const { status, savedAt, target, recovery, restoreDraft, discardDraft } =
  useAutosave({ docId, content, serverContent: doc.content, serverRevision: doc.revision });

{recovery && (
  <Banner>
    {recovery.conflict
      ? "A newer version exists on the server, and you have unsaved local changes from "
      : "Restore unsaved changes from "}
    {new Date(recovery.draft.savedAt).toLocaleTimeString()}?
    <button onClick={() => setContent(restoreDraft() ?? content)}>Restore</button>
    <button onClick={discardDraft}>Discard</button>
  </Banner>
)}

<SaveIndicator status={status} savedAt={savedAt} target={target} />
```

Design notes:

- **Autosave pauses while a recovery prompt is open.** Otherwise the first tick would overwrite the recoverable draft with the server's content, which is exactly the lost-edit bug you're fixing.
- **Conflict handling is detection only.** When `recovery.conflict` is true, the hook doesn't merge; it lets you show a different prompt. If the user restores, their draft is saved against the current revision and overwrites the newer server version. If that's not acceptable, have `saveToServer` reject on a revision mismatch and add a diff or merge step.
- **Recovery after a crash works because the draft is in `localStorage`.** The timer itself is intentionally ephemeral, since on reload the hook just compares the stored draft with the server version.
- **Draft clearing:** It happens only after a confirmed server save with no newer typing, so a failed or slow request never costs edits.
- **Retries:** A failed server save is retried on every tick, with no backoff. Add one if the server is sensitive to that.

How large are your documents, and do multiple people edit the same one? That would tell me whether 5 seconds and overwrite-on-restore are safe, or whether you need debouncing, a separate server interval, or real conflict merging.

