Here's a loader that ties together the sample-size function and the cache from earlier. It adds the safeguards that matter for OOMs on low-RAM devices: capped concurrent decodes, cancellation when views are recycled, waiting for layout before sizing, EXIF handling, and a retry on `OutOfMemoryError`.

```kotlin
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Matrix
import android.view.View
import android.view.ViewTreeObserver
import android.widget.ImageView
import androidx.exifinterface.media.ExifInterface
import kotlinx.coroutines.*
import java.io.IOException
import java.util.WeakHashMap
import kotlin.coroutines.resume

class ImageLoader(
    private val cache: BitmapMemoryCache,
    private val scope: CoroutineScope,                 // e.g. viewLifecycleOwner.lifecycleScope (Main)
    private val config: Bitmap.Config = Bitmap.Config.RGB_565,
    maxConcurrentDecodes: Int = 2
) {
    // Caps how many bitmaps can be mid-decode at once.
    private val decodeDispatcher = Dispatchers.IO.limitedParallelism(maxConcurrentDecodes)

    // Main-thread only. One active request per view.
    private val jobs = WeakHashMap<ImageView, Job>()

    fun load(view: ImageView, path: String) {
        jobs.remove(view)?.cancel()

        // Fast path: already cached and size known, so set synchronously with no flicker.
        if (view.width > 0 && view.height > 0) {
            cache.get(BitmapMemoryCache.key(path, view.width, view.height))?.let {
                view.setImageBitmap(it)
                return
            }
        }

        view.setImageDrawable(null) // don't show a stale image in a recycled view

        jobs[view] = scope.launch {
            val (w, h) = view.awaitSize()
            val bmp = loadBitmap(path, w, h) ?: return@launch
            view.setImageBitmap(bmp) // skipped if cancelled: withContext throws first
        }
    }

    /** Call from onViewRecycled. */
    fun cancel(view: ImageView) {
        jobs.remove(view)?.cancel()
    }

    private suspend fun loadBitmap(path: String, w: Int, h: Int): Bitmap? {
        val key = BitmapMemoryCache.key(path, w, h)
        cache.get(key)?.let { return it }

        return withContext(decodeDispatcher) {
            decode(path, w, h)?.also { cache.put(key, it) } // cache even if the request is cancelled
        }
    }

    private fun decode(path: String, reqW: Int, reqH: Int): Bitmap? {
        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        BitmapFactory.decodeFile(path, bounds)
        if (bounds.outWidth <= 0 || bounds.outHeight <= 0) return null

        val orientation = try {
            ExifInterface(path).getAttributeInt(
                ExifInterface.TAG_ORIENTATION, ExifInterface.ORIENTATION_NORMAL
            )
        } catch (e: IOException) {
            ExifInterface.ORIENTATION_NORMAL
        }

        // The view size is in display orientation, so swap the file's dimensions for 90/270 cases.
        val swap = orientation == ExifInterface.ORIENTATION_ROTATE_90 ||
                orientation == ExifInterface.ORIENTATION_ROTATE_270 ||
                orientation == ExifInterface.ORIENTATION_TRANSPOSE ||
                orientation == ExifInterface.ORIENTATION_TRANSVERSE
        val srcW = if (swap) bounds.outHeight else bounds.outWidth
        val srcH = if (swap) bounds.outWidth else bounds.outHeight

        var sample = calculateInSampleSize(srcW, srcH, reqW, reqH)

        repeat(2) { // one retry at half resolution if we hit OOM
            try {
                val opts = BitmapFactory.Options().apply {
                    inSampleSize = sample
                    inPreferredConfig = config
                }
                val decoded = BitmapFactory.decodeFile(path, opts) ?: return null
                return applyOrientation(decoded, orientation)
            } catch (e: OutOfMemoryError) {
                cache.evictAll()
                sample *= 2
            }
        }
        return null
    }

    private fun applyOrientation(src: Bitmap, orientation: Int): Bitmap {
        val m = Matrix()
        when (orientation) {
            ExifInterface.ORIENTATION_ROTATE_90 -> m.postRotate(90f)
            ExifInterface.ORIENTATION_ROTATE_180 -> m.postRotate(180f)
            ExifInterface.ORIENTATION_ROTATE_270 -> m.postRotate(270f)
            ExifInterface.ORIENTATION_FLIP_HORIZONTAL -> m.postScale(-1f, 1f)
            ExifInterface.ORIENTATION_FLIP_VERTICAL -> m.postScale(1f, -1f)
            ExifInterface.ORIENTATION_TRANSPOSE -> { m.postRotate(90f); m.postScale(-1f, 1f) }
            ExifInterface.ORIENTATION_TRANSVERSE -> { m.postRotate(-90f); m.postScale(-1f, 1f) }
            else -> return src
        }
        val out = Bitmap.createBitmap(src, 0, 0, src.width, src.height, m, true)
        if (out !== src) src.recycle() // safe: the intermediate was never cached or displayed
        return out
    }
}

/** Suspends until the view has a non-zero size. */
private suspend fun View.awaitSize(): Pair<Int, Int> {
    if (width > 0 && height > 0) return width to height
    return suspendCancellableCoroutine { cont ->
        val listener = object : ViewTreeObserver.OnPreDrawListener {
            override fun onPreDraw(): Boolean {
                if (width > 0 && height > 0) {
                    if (viewTreeObserver.isAlive) viewTreeObserver.removeOnPreDrawListener(this)
                    cont.resume(width to height)
                }
                return true
            }
        }
        viewTreeObserver.addOnPreDrawListener(listener)
        cont.invokeOnCancellation {
            if (viewTreeObserver.isAlive) viewTreeObserver.removeOnPreDrawListener(listener)
        }
    }
}
```

